import React, { useState, useEffect } from 'react';
import restaurantService from '../services/restaurantService';
import { useAuth } from '../hooks/useAuth';

const AdminDashboardPage = () => {
  const [restaurants, setRestaurants] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const { token } = useAuth();

  useEffect(() => {
    const fetchRestaurants = async () => {
      setLoading(true);
      setError('');
      try {
        const allRestaurants = await restaurantService.getAllRestaurantsAdmin(token);
        setRestaurants(allRestaurants);
      } catch (err) {
        setError(err.message || 'Failed to fetch restaurants.');
      } finally {
        setLoading(false);
      }
    };

    fetchRestaurants();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [token]);

  const handleVerify = async (restaurantId) => {
    try {
      await restaurantService.verifyRestaurant(restaurantId, token);
      setRestaurants(restaurants.map(r =>
        r._id === restaurantId ? { ...r, isVerified: true } : r
      ));
      console.log(`Restaurant ${restaurantId} verified.`);
    } catch (err) {
      setError(err.message || 'Failed to verify restaurant.');
    }
  };

  if (loading) {
    return <div>Loading restaurants...</div>;
  }

  if (error) {
    return <div style={{ color: 'red' }}>{error}</div>;
  }

  return (
    <div>
      <h2>Admin Dashboard - Restaurant Management</h2>
      {error && <p style={{ color: 'red' }}>{error}</p>}
      {restaurants.length === 0 ? (
        <p>No restaurants registered.</p>
      ) : (
        <ul>
          {restaurants.map(restaurant => (
            <li key={restaurant._id}>
              {restaurant.name} - Owner: {restaurant.ownerId?.username || 'N/A'}
              {!restaurant.isVerified && (
                <button onClick={() => handleVerify(restaurant._id)}>Verify</button>
              )}
              {restaurant.isVerified && <span style={{ color: 'green' }}>Verified</span>}
              {/* Add more admin actions here if needed */}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default AdminDashboardPage;
